/** NeoSmartUXUI Commerce Vertical — local implementation, not a published API. */
export type Money={amount:number;currency:string};
export type ProductOffer={id:string;price:Money;interval?:string};
export type ProductView={id:string;name:string;summary?:string;offers:ProductOffer[];route?:string;image?:{src:string;alt:string};status?:string};
export type MediaImage={src:string;alt:string;label:string};
export type CartLineView={id:string;label:string;quantity:number;unitPrice:Money;subtotal:Money};
export type PriceAdjustment={label:string;amount:Money};
export type OrderSummaryView={subtotal:Money;total:Money;discounts?:PriceAdjustment[];taxes?:PriceAdjustment[]};
export type LicenseState='active'|'grace'|'expired'|'cancelled'|'refunded';
export type LicenseView={id:string;productId:string;status:LicenseState;maskedKey?:string;updatesThrough?:string|null};
export type EntitlementView={id:string;productId:string;downloadAllowed:boolean};
export type DOMRenderer=(...args:any[])=>HTMLElement;
export function formatMoney(money:Money,locale?:string):string;
export function renderProductPrice(money:Money,options?:{locale?:string;compareAt?:Money;interval?:string;renewal?:string}):HTMLElement;
export function renderProductCard(product:ProductView,options?:{offerId?:string;locale?:string}):HTMLElement;
export function renderProductGallery(media:{label:string;images:MediaImage[]}):HTMLElement;
export function renderCartLine(line:CartLineView,options?:{onRemove?:(lineId:string)=>Promise<unknown>|unknown;locale?:string}):HTMLElement;
export function renderOrderSummary(quote:OrderSummaryView,options?:{locale?:string;heading?:string}):HTMLElement;
export function renderLicenseStatus(license:LicenseView):HTMLElement;
export function renderSeatUsage(info:{label:string;used:number;capacity:number}):HTMLElement;
export function renderDownloadEntitlement(entitlement:EntitlementView,options?:{onRequest?:(entitlementId:string)=>Promise<unknown>|unknown}):HTMLElement;
export const COMMERCE_RENDERERS:Readonly<Record<string,DOMRenderer>>;

export type RichProductView=ProductView&{description?:string;availability?:string};
export type CatalogMedia={label:string;preview?:{src:string;alt:string};code?:string;files?:string[]};
export type ReviewSummary={rating:number;count:number;caption?:string};
export type LicenseOffer=ProductOffer&{label:string;description?:string;features?:string[]};
export function renderProductDetail(product:RichProductView,options?:{offerId?:string;locale?:string}):HTMLElement;
export function renderProductMedia(media:CatalogMedia,options?:{initial?:'preview'|'code'|'files'}):HTMLElement;
export function renderReviewSummary(review:ReviewSummary):HTMLElement;
export function renderLicenseSelector(model:{label?:string;offers:LicenseOffer[];selectedId?:string},options?:{onChange?:(id:string)=>void;locale?:string}):HTMLElement;
export function renderRenewalNote(note:{label?:string;message:string;renewsAt?:string;policyUrl?:string}):HTMLElement;
export function renderPricingTier(offer:LicenseOffer,options?:{onSelect?:(id:string)=>Promise<unknown>|unknown;locale?:string}):HTMLElement;
export const COMMERCE_WAVE2_RENDERERS:Readonly<Record<string,DOMRenderer>>;

export type CheckoutStep={id:string;label:string};
export type PaymentOption={id:string;label:string;description?:string};
export type CouponResult={status:'accepted'|'rejected';message:string};
export type RecoveryResult={status:'recovered'|'failed';message:string};
export type BillingUpdate={legalName:string;billingEmail:string;billingAddress:string;taxIdentifier:string};
export function renderCoupon(model?:{label?:string;placeholder?:string;appliedCode?:string},opts?:{onApply?:(code:string)=>Promise<CouponResult>|CouponResult}):HTMLElement;
export function renderCheckoutField(model:{id:string;label:string;value?:string;required?:boolean;type?:'text'|'email'|'tel';autocomplete?:string;helpText?:string;error?:string},opts?:{onChange?:(id:string,value:string)=>void}):HTMLElement;
export function renderInvoiceDetails(details:Partial<BillingUpdate>,opts?:{onSave?:(draft:BillingUpdate)=>Promise<{status:'saved'|'rejected';message:string}>}):HTMLElement;
export function renderCheckoutSteps(model:{steps:CheckoutStep[];currentId:string;status?:'ready'|'processing'|'failed'|'recovered'}):HTMLElement;
export function renderPaymentMethod(model:{methods:PaymentOption[];selectedId?:string},opts?:{onChange?:(id:string)=>void}):HTMLElement;
export function renderPaymentFailure(model:{code:string;message:string;retryable?:boolean},opts?:{onRetry?:(code:string)=>Promise<unknown>|unknown}):HTMLElement;
export function renderPaymentRecovery(model:{quoteId:string;message:string;status?:'ready'|'failed'|'recovered'},opts?:{onRecover?:(quoteId:string)=>Promise<RecoveryResult>|RecoveryResult}):HTMLElement;
export function renderProcessingState(model:{label?:string;message?:string;attemptId?:string}):HTMLElement;
export function renderOrderConfirmation(model:{id:string;status:'confirmed';total?:Money;entitlements?:{productId:string;delivered:boolean}[]},opts?:{locale?:string}):HTMLElement;
export function renderReceipt(model:{id:string;orderId:string;status:'paid';amount:Money;paidAt?:string;invoiceId?:string},opts?:{locale?:string}):HTMLElement;
export const COMMERCE_WAVE3_RENDERERS:Readonly<Record<string,DOMRenderer>>;
